CREATE TABLE preferences(user_id TEXT PRIMARY KEY REFERENCES users(id), value JSONB NOT NULL DEFAULT '{}', updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE audit_log(id BIGSERIAL PRIMARY KEY, actor_id TEXT, action TEXT NOT NULL, resource TEXT NOT NULL, details JSONB NOT NULL DEFAULT '{}', created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX audit_created ON audit_log(created_at DESC);
CREATE TABLE devices(token TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),session_id TEXT NOT NULL REFERENCES auth_sessions(id),platform TEXT NOT NULL CHECK(platform IN ('ios','android','web')),updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE outbox(id BIGSERIAL PRIMARY KEY,kind TEXT NOT NULL CHECK(kind IN ('email','push','push_receipt')),payload JSONB NOT NULL, status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','processing','sent','failed','skipped')),attempts INTEGER NOT NULL DEFAULT 0, available_at TIMESTAMPTZ NOT NULL DEFAULT now(), locked_at TIMESTAMPTZ,last_error TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),completed_at TIMESTAMPTZ);
CREATE INDEX outbox_ready ON outbox(status,available_at);
CREATE TABLE support_tickets(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),subject TEXT NOT NULL,message TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'open' CHECK(status IN ('open','resolved')),reply TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE payments(id TEXT PRIMARY KEY,trip_id TEXT NOT NULL UNIQUE REFERENCES trips(id),user_id TEXT NOT NULL REFERENCES users(id),amount INTEGER NOT NULL CHECK(amount>0),currency TEXT NOT NULL DEFAULT 'cop',status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','paid','failed','refunded','cash_confirmed','partially_refunded')),checkout_id TEXT UNIQUE,checkout_url TEXT,checkout_expires_at TIMESTAMPTZ,generation INTEGER NOT NULL DEFAULT 0,payment_intent_id TEXT UNIQUE,refunded_amount BIGINT NOT NULL DEFAULT 0,provider_amount BIGINT,provider_fee BIGINT,provider_net BIGINT,reconciled_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE stripe_events(id TEXT PRIMARY KEY,type TEXT NOT NULL,payment_id TEXT,status TEXT NOT NULL DEFAULT 'processed',created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE reconciliation_runs(id TEXT PRIMARY KEY,actor_id TEXT,processed INTEGER NOT NULL DEFAULT 0,mismatches INTEGER NOT NULL DEFAULT 0,created_at TIMESTAMPTZ NOT NULL DEFAULT now());

CREATE TABLE payment_attempts(checkout_id TEXT PRIMARY KEY,payment_id TEXT NOT NULL REFERENCES payments(id),generation INTEGER NOT NULL,status TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(payment_id,generation));
CREATE FUNCTION protect_audit_log() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'audit_log is append-only'; END $$;
CREATE TRIGGER audit_log_immutable BEFORE UPDATE OR DELETE ON audit_log FOR EACH ROW EXECUTE FUNCTION protect_audit_log();
